def block(hdr_idx):
    hdr = rows[hdr_idx]
    # expand: each label covers 3 replicate columns
    cols = []
    lab = None
    for j,v in enumerate(hdr):
        if v not in (None,'') and j>0: lab = str(v).strip()
        if j>0: cols.append((j,lab))
    return cols
